/** Platzhalter-Neu oder gefülltes Neu (Badge / Sperre bis Freigabe). */
export function isNeuTopic(id: string): boolean {
  return PLACEHOLDER_NEU_TOPIC_IDS.has(id) || FILLED_NEU_TOPIC_IDS.has(id)
}

